Ext._define('judicial.parts.AttachedGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'judicial.parts.AttachedWindow',

    actionColumnWidth: 85,

    togglePublish: function(pk) {
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'atualizando publicidade...'});

        mask.show();
        this.factoryRestful().togglePublish(
            pk,
            {
                scope: this,
                fn: function() {
                    this.getStore().reload();
                }
            },
            {
                scope: this,
                fn: function(message) {
                    Ext.Msg.show({
                        title: 'Mudando publicidade',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                }
            },
            {
                scope: this,
                fn: function() {
                    mask.hide();
                }
            }
        );
    },

    getConfigActions: function(cfg) {
        if(!this._configActions) {
            this._configActions = judicial.parts.AttachedGrid.superclass.getConfigActions.call(this, cfg);

            if(this.hideActions.indexOf('publish') < 0 && this.restWindow) {
                this._configActions = [{
                    iconCls: 'icon-16px icon-judicial icon-ejud-public',
                    tooltip: 'Publicar',
                    handler: function(action, index) {
                        var record = this.getStore().getAt(index);
                        if(record) {
                            this.togglePublish(record.get('pk'));
                            console.log(record.data);
                        }
                    }
                }].concat(this._configActions);
            }
        }

        return this._configActions;
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {
                        'header': '',
                        'dataIndex': 'icons',
                        'width': 50,
                        'menuDisabled': true,
                        'renderer': core.rendererIconGrid
                    },
                    {header: 'Título', dataIndex: 'title', id: 'autoExpandColumn'},
                    {header: 'Enviado por', dataIndex: 'send_by', width: 150},
                    {header: 'Data', dataIndex: 'send_at', width: 120, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')}
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'judicial.parts.AttachedRestful',
    'judicial.parts.AttachedGrid'
);
